import { FC } from 'react';

import { Card, Flex, FlexProps, Typography } from 'antd';
import cn from 'classnames';

import MagnetIcon from 'assets/images/icons/magnet.svg?react';
import PictureIcon from 'assets/images/icons/picture.svg?react';
import WalletIcon from 'assets/images/icons/wallet.svg?react';
import { ChannelStatChange } from 'entities/Channel';
import { OverlayLoader } from 'shared/ui';

import styles from './ReportSummaryItem.module.scss';

interface IReportSummaryItemProps extends FlexProps {
	icon?: 'picture' | 'wallet' | 'magnet';
	summ: string;
	description: string;
	arrow: 'up' | 'down' | 'equal';
	isDashboard?: boolean;
	isFetching?: boolean;
}

export const ReportSummaryItem: FC<IReportSummaryItemProps> = ({
	className,
	icon,
	summ,
	description,
	arrow,
	isDashboard,
	isFetching,
	...props
}) => {
	const icons = {
		picture: <PictureIcon />,
		wallet: <WalletIcon />,
		magnet: <MagnetIcon />,
	};

	return (
		<Card {...props} variant={'borderless'} className={cn(className, styles.item, { [styles.dashboard]: isDashboard })}>
			{isFetching && <OverlayLoader />}

			<Flex align="center" gap={8}>
				{icon && (
					<Flex align="center" justify="center" className={cn(styles.icon, styles[icon])}>
						{icons[icon]}
					</Flex>
				)}
				<Flex vertical gap={isDashboard ? 4 : 0}>
					<ChannelStatChange arrow={arrow} iconSize={22}>
						<Typography.Text className={styles.title}>{summ}</Typography.Text>
					</ChannelStatChange>
					<Typography.Text type="secondary" className={styles.description}>
						{description}
					</Typography.Text>
				</Flex>
			</Flex>
		</Card>
	);
};
